     wide_bad||identity_bad||
     (reply_active&&rep_age==0&&!matching_reply);
 assign request_checked_v=active&&req_age==0&&!endpoint_fault&&!checked_error;
 assign reply_checked_v=active&&reply_active&&rep_age==0&&matching_reply&&!endpoint_fault&&!checked_error;
 // Early held publication is refused until the matching check completes.
 // A wrong identity quarantines; a held correct publication is consumed once.
 wire consume=published_reply_v&&reply_checked_v&&!sent;
 wire ack_n=consume&&warm&&held_reply.visible[1];
 wire [23:0] ack_word_n={9'b0,held_reply.wa[15+:15]};
 wire [15:0] ack_mask_n=held_reply.wm[16+:16];
 localparam [2:0] AGE=FPIPE?3'd6:3'd5;
 generate if(FPIPE) begin : g_ack_reg
`ifndef SYNTHESIS
  initial if(!MARGIN) $fatal(1,"FPIPE needs MARGIN");
`endif
  // head ACK launched from registers: the debt owner sees the receipt one cycle later
  (* keep=1,dont_touch=1 *) reg ack_v_q;
  reg [7:0] ack_id_q;reg [23:0] ack_word_q;reg [15:0] ack_mask_q;
  always @(posedge fast_clk) begin
   if(!cold_n) ack_v_q<=0; else ack_v_q<=ack_n;
   ack_id_q<=id;ack_word_q<=ack_word_n;ack_mask_q<=ack_mask_n;
  end
  assign head_ack_v=ack_v_q;assign head_ack_id=ack_id_q;
  assign head_ack_word=ack_word_q;assign head_ack_mask=ack_mask_q;
 end else begin : g_ack_direct
  assign head_ack_v=ack_n;assign head_ack_id=id;
  assign head_ack_word=ack_word_n;assign head_ack_mask=ack_mask_n;
 end endgenerate
 assign guard_busy=active;
 assign captured_request=source_packet;assign captured_request_check=source_check;
 assign captured_reply=held_reply;assign captured_reply_check=held_check;
 always @(posedge fast_clk) begin
  if(!cold_n) begin
   active<=0;active_check<=1;reply_active<=0;reply_active_check<=1;
   req_age<=0;req_age_check<=3'b111;rep_age<=0;rep_age_check<=3'b111;
   warm<=0;warm_check<=1;sent<=0;sent_check<=1;
   protocol_fault<=0;protocol_fault_check<=1;id<=0;id_check<=8'hff;
  end else begin
   if(request_take) begin
    active<=1;active_check<=0;reply_active<=0;reply_active_check<=1;
    req_age<=AGE;req_age_check<=~AGE;rep_age<=0;rep_age_check<=3'b111;
    warm<=request_warm;warm_check<=~request_warm;id<=request_id;id_check<=~request_id;
    sent<=0;sent_check<=1;
   end else if(active&&req_age!=0) begin req_age<=req_age-1'b1;req_age_check<=~(req_age-3'd1);end
   if(reply_take) begin reply_active<=1;reply_active_check<=0;rep_age<=AGE;rep_age_check<=~AGE;end
   else if(reply_active&&rep_age!=0) begin rep_age<=rep_age-1'b1;rep_age_check<=~(rep_age-3'd1);end
   if(consume) begin sent<=1;sent_check<=0;end
   // Release storage only after matching real checked visibility. The parent
   // independently consumes the warm ACK on this same edge.
   if(active&&sent&&!published_reply_v) begin active<=0;active_check<=1;end
   if(metadata_bad||bounds_fault||identity_bad||
       (request_accept&&!request_take)||
       (checked_reply_capture&&!reply_take)||
       (published_reply_v&&reply_active&&rep_age==0&&!matching_reply)) begin
    protocol_fault<=1;protocol_fault_check<=0;
   end
  end
 end
endmodule

(* keep_hierarchy *)
module ot_hdc_v41_fh_checked_bank #(parameter integer BITS=32, MARGIN=0, FPIPE=0)(
 input wire clk,cold_n,load,input wire [BITS-1:0] d,
 (* keep=1,dont_touch=1 *) output reg [BITS-1:0] q,check,output wire bad
);
 // MARGIN: data registered twice at the bank, load (already one kept copy late) once more
 wire [BITS-1:0] dl;
 wire ll;
 generate if(MARGIN) begin : g_pipe
  reg [BITS-1:0] d1,d2;
  reg l2;
  always @(posedge clk) begin d1<=d; d2<=d1; l2<=cold_n&&load; end
  assign dl=d2; assign ll=l2;
 end else begin : g_direct
  assign dl=d; assign ll=load;
 end endgenerate
 (* keep=1,dont_touch=1 *) reg fault,fault_check;
 wire mismatch=q!=~check;
 wire bad_n=mismatch||fault||fault!=~fault_check;
 // FPIPE: the bank's bad flag leaves a kept per-bank flop (the local pair check stays inside the bank)
 generate if(FPIPE) begin : g_bad_reg
  (* keep=1,dont_touch=1 *) reg bad_q;
  always @(posedge clk) if(!cold_n) bad_q<=0; else bad_q<=bad_n;
  assign bad=bad_q;
 end else begin : g_bad_direct
  assign bad=bad_n;
 end endgenerate
 always @(posedge clk) begin
  if(!cold_n) begin q<=0;check<={BITS{1'b1}};fault<=0;fault_check<=1;end
  else begin
   if(ll&&!bad_n) begin q<=dl;check<=~dl;end
   if(bad_n) begin fault<=1;fault_check<=0;end
  end
 end
endmodule

// kept copies for the margin-first endpoint broadcast (cold_n, take)
(* keep_hierarchy *)
module ot_hdc_v41_fh_cold_copy(input wire clk,d,output reg q);
 always @(posedge clk) q<=d;
endmodule
(* keep_hierarchy *)
module ot_hdc_v41_fh_take_copy(input wire clk,cold_n,d,output reg q);
 always @(posedge clk) if(!cold_n) q<=0; else q<=d;
endmodule

(* keep_hierarchy *)
module ot_hdc_v41_fh_checked_reduce #(parameter integer BITS=131)(
 input wire clk,cold_n,input wire [BITS-1:0] bad,output wire fault
);
 localparam integer NG=(BITS+7)/8,NC=(NG+3)/4;
 (* keep=1,dont_touch=1 *) reg [NG-1:0] local_bad,local_check;
 (* keep=1,dont_touch=1 *) reg [NC-1:0] cluster_bad,cluster_check;
 (* keep=1,dont_touch=1 *) reg final_bad,final_check;
 for(genvar g=0;g<NG;g=g+1) begin : g_local_check
  localparam integer N=(BITS-g*8>=8)?8:BITS-g*8;
  always @(posedge clk) if(!cold_n)begin local_bad[g]<=0;local_check[g]<=1;end
   else begin local_bad[g]<=|bad[g*8+:N];local_check[g]<=~(|bad[g*8+:N]);end
 end
 for(genvar c=0;c<NC;c=c+1) begin : g_cluster_check
  localparam integer N=(NG-c*4>=4)?4:NG-c*4;
  wire f=(|local_bad[c*4+:N])||local_bad[c*4+:N]!=~local_check[c*4+:N];
  always @(posedge clk) if(!cold_n)begin cluster_bad[c]<=0;cluster_check[c]<=1;end
   else begin cluster_bad[c]<=f;cluster_check[c]<=~f;end
 end
 wire f=(|cluster_bad)||cluster_bad!=~cluster_check;
 always @(posedge clk) if(!cold_n)begin final_bad<=0;final_check<=1;end
  else begin final_bad<=f;final_check<=~f;end
 assign fault=final_bad||final_bad!=~final_check||
     local_bad!=~local_check||cluster_bad!=~cluster_check;
endmodule

(* keep_hierarchy *)
module ot_hdc_v41_fh_checked_match #(parameter integer BITS=32)(
 input wire clk,cold_n,input wire [BITS-1:0] a,b,
 (* keep=1,dont_touch=1 *) output reg match,check
);
 always @(posedge clk) begin
  if(!cold_n) begin match<=0;check<=1;end
  else begin match<=a==b;check<=~(a==b);end
 end
endmodule

out/head_q_safe__pin_wdata_skip/ot_hdc_v.text:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------------------------------------------
// ot_hdc_v41_fh_quad: one hardened QUADRANT of the margin-first fused head (redesign pass 2026-10-06). Four identical
// instances (gid strap 0..3) plus ot_hdc_v41_fh_head_top form ot_hdc_v41_fh_head_q, which is cycle-identical to
// ot_hdc_v41_fh_macro_ctx MARGIN=1 HARD_LANE=1 (CAPTURE, ALAT 7, RETURN_EXTRA 5, PROTECT_SPLIT 1). Nothing is added:
// the group's registers of fh_ctx / fh_add / sram_return_hardened are only regrouped into the quadrant:
//   in : the write mask / data ADDR_PIPE stage-1 registers (s_wmask, s_wdata), res_u, mask_q, o_mask1, o_addr1, the leaf-row / argmax-index / index-address group replicas, the group
//        copies of the return valid (u_rvg), fused select (u_selg) and index-write go (u_iwgg), the per-lane
//        request registers (ADDR_PIPE stage 2) - every input pin lands on one of these flops;
//   core: 16 hardened SRAM lane leaves (bank_id = {gid, lane}), the res_h delay line, 16 capture + FP32 add LAT 7
//        lanes, the fused/plain result select, the o_*1 / index-write port, the argmax leaves;
//   out: leaf, o_data, o_mask, o_addr, poison, group_fault - all flops.
// Index writes belong to group 0 (gid strap); o_addr takes the index address from its group replica iw_e_x, equal
// to the top's iaddr_r whenever an index write is selected (iaddr_r is held from go_fus acceptance to the write).
// ---------------------------------------------------------------------------------------------------------------
module ot_hdc_v41_fh_quad #(
    parameter integer W = 16, AW = 24, NW = 16, ALAT = 7, RETURN_EXTRA = 5,
    // QPIN (redesign r2): the request inputs (rok/rrow/wok/wrow) and the write mask/data land on a group input-pin
    // register before the per-lane request registers (ADDR_PIPE 3, +1 request cycle, RETURN_EXTRA = 6): no input pin
    // fans out across the quadrant.
    parameter integer QPIN = 0
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire [1:0]        gid,
    input  wire              rok,
    input  wire [8:0]        rrow,
    input  wire              wok,
    input  wire [8:0]        wrow,
    input  wire [W-1:0]      wr_mask_in,
    input  wire [W*32-1:0]   wr_data_in,
    input  wire [W*32-1:0]   res_in,
    input  wire [W-1:0]      o_mask1_in,
    input  wire [AW-1:0]     o_addr1_in,
    input  wire [W-1:0]      leaf_mask_in,
    input  wire [NW-1:0]     leaf_row_in,
    input  wire [NW-1:0]     am_idx_in,
    input  wire              rv_mid,
    input  wire              fsel_m,
    input  wire              iwg_m,
    input  wire [AW-1:0]     iw_e,
    output wire [(1+32+NW)*W-1:0] leaf,
    output reg  [W*32-1:0]   o_data,
    output reg  [W-1:0]      o_mask,
    output reg  [AW-1:0]     o_addr,
    output wire [W-1:0]      poison,
    output reg               group_fault
);
    localparam integer LW = $clog2(W);
    localparam integer CW = 1 + 32 + NW;
    // ---- input flops ---------------------------------------------------------------------------------------
    reg [W*32-1:0] res_u;
    reg [W-1:0] mask_q, o_mask1;
    reg [AW-1:0] o_addr1;
    always @(posedge clk) begin res_u <= res_in; mask_q <= leaf_mask_in; o_mask1 <= o_mask1_in; o_addr1 <= o_addr1_in; end
    wire [NW-1:0] row_qg, am_idx_x;
    wire [AW-1:0] iw_e_x;
    ot_hdc_v41_fh_kvec #(.N(NW)) u_rowq (.clk(clk), .d(leaf_row_in), .q(row_qg));
    ot_hdc_v41_fh_kvec #(.N(NW)) u_amg (.clk(clk), .d(am_idx_in), .q(am_idx_x));
    ot_hdc_v41_fh_kvec #(.N(AW)) u_iag (.clk(clk), .d(iw_e), .q(iw_e_x));
    wire protected_vg, fsel_g, iwg_g;
    ot_hdc_v41_fh_kreg u_rvg (.clk(clk), .rst_n(rst_n), .d(rv_mid), .q(protected_vg));
    ot_hdc_v41_fh_kreg u_selg (.clk(clk), .rst_n(rst_n), .d(fsel_m), .q(fsel_g));
    ot_hdc_v41_fh_kreg u_iwgg (.clk(clk), .rst_n(rst_n), .d(iwg_m), .q(iwg_g));
    // ---- SRAM lanes: ADDR_PIPE stage 2 (kept per-lane request register) + hardened lane leaf -----------------
    wire [W*32-1:0] ra_q;
    reg [W-1:0] s_wmask;
    reg [W*32-1:0] s_wdata;
    wire rok_q, wok_q;
    wire [8:0] rrow_q, wrow_q;
    generate if (QPIN) begin : g_pin
        reg [W-1:0] s_wmask0;
        reg [W*32-1:0] s_wdata0;
        reg rok_p, wok_p;
        reg [8:0] rrow_p, wrow_p;
        always @(posedge clk or negedge rst_n)
            if (!rst_n) begin rok_p <= 1'b0; wok_p <= 1'b0; end
            else begin rok_p <= rok; wok_p <= wok; end
        always @(posedge clk) begin rrow_p <= rrow; wrow_p <= wrow; s_wmask0 <= wr_mask_in; s_wdata0 <= wr_data_in;
                                    s_wmask <= s_wmask0; s_wdata <= wr_data_in; end
        assign rok_q = rok_p; assign wok_q = wok_p; assign rrow_q = rrow_p; assign wrow_q = wrow_p;
    end else begin : g_nopin
        always @(posedge clk) begin s_wmask <= wr_mask_in; s_wdata <= wr_data_in; end
        assign rok_q = rok; assign wok_q = wok; assign rrow_q = rrow; assign wrow_q = wrow;
    end endgenerate
    genvar l;
    generate for (l = 0; l < W; l = l + 1) begin : g_bank
        wire r_ok, w_ok;
        wire [8:0] r_row, w_row;
        wire [31:0] w_d;
        ot_hdc_v41_fh_quad_lane_req u_req (.clk(clk), .rst_n(rst_n),
            .read_ok_d(rok_q), .read_row_d(rrow_q), .write_ok_d(wok_q && s_wmask[l]), .write_row_d(wrow_q), .wr_data_d(s_wdata[32*l+:32]),
            .read_ok(r_ok), .read_row(r_row), .write_ok(w_ok), .write_row(w_row), .wr_data(w_d));
        ot_hdc_v41_fh_sram_lane_hardened u_lane (
            .bank_id({gid, 4'(l)}),
            .clk(clk), .rst_n(rst_n), .read_ok(r_ok), .read_row(r_row),
            .write_ok(w_ok), .write_row(w_row), .wr_data(w_d),
            .rd_data(ra_q[32*l+:32]), .rd_valid(), .corrected(),
            .poisoned(poison[l]), .wr_committed());
    end endgenerate
    // ---- fused add lanes (ot_hdc_v41_fh_add CAPTURE + TREE, one group) --------------------------------------
    wire [W*32-1:0] res_h;
    ot_hdc_delay #(.W(W*32), .D(2 + RETURN_EXTRA)) u_rh (.clk(clk), .rst_n(rst_n), .d(res_u), .q(res_h));
    wire [W*32-1:0] fsum;
    wire [W-1:0] ffault, fused_lane_v, iwg;
    generate for (l = 0; l < W; l = l + 1) begin : g_fadd
        reg [31:0] addend_r, result_r;
        wire valid_in;
        always @(posedge clk) begin addend_r <= ra_q[32*l+:32]; result_r <= res_h[32*l+:32]; end
        ot_hdc_v41_fh_kreg u_v (.clk(clk), .rst_n(rst_n), .d(protected_vg), .q(valid_in));
        wire [1:0] err;
        wire vo;
        ot_hdc_fp32_add_lat #(.LAT(ALAT)) u_add (.clk(clk), .rst_n(rst_n), .valid_in(valid_in), .a(addend_r),
                                                 .b(result_r), .y(fsum[32*l +: 32]), .err(err), .valid_out(vo));
        assign ffault[l] = vo && (err != 2'd0);
        ot_hdc_v41_fh_kreg u_sel (.clk(clk), .rst_n(rst_n), .d(fsel_g), .q(fused_lane_v[l]));
        ot_hdc_v41_fh_kreg u_iwg (.clk(clk), .rst_n(rst_n), .d(iwg_g), .q(iwg[l]));
    end endgenerate
    always @(posedge clk or negedge rst_n)
        if (!rst_n) group_fault <= 1'b0; else group_fault <= |ffault;
    wire [W*32-1:0] res;
    generate for (l = 0; l < W; l = l + 1) begin : g_res
        assign res[32*l+:32] = fused_lane_v[l] ? fsum[32*l+:32] : res_u[32*l+:32];
    end endgenerate
    // ---- result port: o_*1 stage, the argmax-index write (group 0) ------------------------------------------
    reg [W*32-1:0] o_data1;
    always @(posedge clk) o_data1 <= res;
    wire idx_group = gid == 2'd0;
    wire [NW-1:0] index_local [0:W-1];
    wire [W-1:0] index_mask_local;
    generate for (l = 0; l < W; l = l + 1) begin : g_index_prepare
        ot_hdc_v41_fh_indexreg #(.NW(NW), .LW(LW), .LANE(l)) u_index (
            .clk(clk), .index_in(am_idx_x), .lane_in(iw_e_x[LW-1:0]),
            .index_q(index_local[l]), .mask_q(index_mask_local[l]));
    end endgenerate
    integer il;
    always @(posedge clk) begin
        for (il = 0; il < W; il = il + 1) begin
            o_data[32*il +: 32] <= iwg[il] ? ((idx_group && index_mask_local[il]) ? {{(32-NW){1'b0}}, index_local[il]} : 32'b0)
                                           : o_data1[32*il +: 32];
            o_mask[il] <= iwg[il] ? (idx_group && index_mask_local[il]) : o_mask1[il];
        end
        o_addr <= iwg[0] ? (idx_group ? (iw_e_x >> LW) : {AW{1'b0}}) : o_addr1;
    end
    // ---- argmax leaves ----------------------------------------------------------------------------------------
    function automatic [31:0] okey(input [31:0] v);
        okey = v[31] ? ~v : {1'b1, v[30:0]};
    endfunction
    generate for (l = 0; l < W; l = l + 1) begin : g_leaf
        reg [CW-1:0] c;
        always @(posedge clk) c <= {mask_q[l], okey(res[32*l +: 32]), row_qg};
        assign leaf[CW*l +: CW] = c;
    end endgenerate
endmodule

// Kept per-lane request register (ADDR_PIPE stage 2), the quadrant's own copy of ot_hdc_v41_fh_lane_req (same logic): the
// quadrant view is synthesised against the hardened lane LEAF (liberty), so it cannot read the lane RTL file.
(* keep_hierarchy *)
module ot_hdc_v41_fh_quad_lane_req(
    input wire clk,rst_n,read_ok_d,write_ok_d,
    input wire [8:0] read_row_d,write_row_d,
    input wire [31:0] wr_data_d,
    output reg read_ok,write_ok,
    output reg [8:0] read_row,write_row,
    output reg [31:0] wr_data
);
    always @(posedge clk or negedge rst_n)
        if(!rst_n) begin read_ok<=0; write_ok<=0; end
        else begin read_ok<=read_ok_d; write_ok<=write_ok_d; end
    always @(posedge clk) begin read_row<=read_row_d; write_row<=write_row_d; wr_data<=wr_data_d; end
endmodule

out/endpoint_fpipe2__pin_data_skip/ot_hd.text:
`timescale 1ns/1ps
// Minimum head physical boundary: copies of the real native fast-domain
// capture registers in ot_dsrom_protected_vm (554d7b0c9/16aa68768).
// These represent existing parent registers, not extra production stages.
// Backend SRAM readback/transport and publication remain actual parent inputs.
// Conditional child proof only; do not substitute this for the parent VM.
(* keep_hierarchy *)
module ot_hdc_v41_fh_vm_endpoint_ctx # (parameter integer ENABLE=0, CHECK_PIPE=0, MARGIN=0, FPIPE=0)(
 input wire fast_clk,cold_n,
 input wire request_accept,request_warm,checked_reply_capture,published_reply_v,
 input wire [31:0] native_ordinal,
 input wire [46:0] request_owner,
 input wire [7:0] request_id,
 input wire [3:0] head_we,
 input wire [95:0] head_addr,
 input wire [63:0] head_mask,
 input wire [2047:0] head_data,
 input wire [ot_dsrom_vm_pkg::REP_BITS-1:0] checked_reply,
 output wire bounds_fault, endpoint_fault,
 output wire [ot_dsrom_vm_pkg::REQ_BITS-1:0] captured_request,captured_request_check,
 output wire [ot_dsrom_vm_pkg::REP_BITS-1:0] captured_reply,captured_reply_check,
 output wire request_checked_v,reply_checked_v,guard_busy,
 output wire head_ack_v,
 output wire [7:0] head_ack_id,
 output wire [23:0] head_ack_word,
 output wire [15:0] head_ack_mask
);
 import ot_dsrom_vm_pkg::*;
 generate if(ENABLE && CHECK_PIPE && FPIPE>=2) begin : g_distributed_check
  // FPIPE=2 (SAFE): every endpoint input lands on a pin register first (+1 on request accept / reply capture /
  // publication and their payloads, uniformly); the checked permission then sees only registered inputs.
  // guard_busy also covers an accepted request still in the pin register, so a parent gating its next request on
  // guard_busy never presents a second request while the first is in flight.
  reg ra_q,rw_q,rc_q,pv_q;
  reg [31:0] ord_q; reg [46:0] own_q; reg [7:0] id_q; reg [3:0] we_q; reg [95:0] addr_q; reg [63:0] mask_q;
  reg [2047:0] data_q; reg [REP_BITS-1:0] rep_q;
  always @(posedge fast_clk) begin
   if(!cold_n) begin ra_q<=0;rw_q<=0;rc_q<=0;pv_q<=0;we_q<=0; end
   else begin ra_q<=request_accept;rw_q<=request_warm;rc_q<=checked_reply_capture;pv_q<=published_reply_v;we_q<=head_we; end
   ord_q<=native_ordinal;own_q<=request_owner;id_q<=request_id;addr_q<=head_addr;mask_q<=head_mask;data_q<=0;rep_q<=checked_reply;
  end
  wire guard_core_busy;
  ot_hdc_v41_fh_checked_permission #(.MARGIN(MARGIN),.FPIPE(FPIPE)) u_guard(.fast_clk(fast_clk),.cold_n_in(cold_n),
   .request_accept(ra_q),.request_warm(rw_q),.checked_reply_capture(rc_q),.published_reply_v(pv_q),
   .native_ordinal(ord_q),.request_owner(own_q),.request_id(id_q),.head_we(we_q),.head_addr(addr_q),.head_mask(mask_q),
   .head_data(data_q),.checked_reply(rep_q),.bounds_fault(bounds_fault),.endpoint_fault(endpoint_fault),
   .captured_request(captured_request),.captured_request_check(captured_request_check),
   .captured_reply(captured_reply),.captured_reply_check(captured_reply_check),
   .request_checked_v(request_checked_v),.reply_checked_v(reply_checked_v),.guard_busy(guard_core_busy),
   .head_ack_v(head_ack_v),.head_ack_id(head_ack_id),.head_ack_word(head_ack_word),.head_ack_mask(head_ack_mask));
  assign guard_busy=guard_core_busy||ra_q;
 end else if(ENABLE && CHECK_PIPE) begin : g_distributed_check
  ot_hdc_v41_fh_checked_permission #(.MARGIN(MARGIN),.FPIPE(FPIPE)) u_guard(.cold_n_in(cold_n),.*);
 end else if(ENABLE) begin : g_native_endpoints
  assign request_checked_v=request_accept&&!endpoint_fault;
  assign reply_checked_v=published_reply_v&&!endpoint_fault;
  assign guard_busy=0;
  wire [1:0] read_enable=0;
  wire [29:0] read_addr=0;
  wire [4:0] write_enable={head_we,1'b0};
  wire [2559:0] write_data={head_data,512'b0};
  wire [79:0] write_mask={head_mask,16'b0};
  wire [74:0] write_addr;
  wire [3:0] bad_address;
  for(genvar g=0;g<4;g=g+1) begin : g_word
   assign write_addr[(g+1)*15+:15]=head_addr[g*24+:15];
   assign bad_address[g]=head_we[g]&&(|head_addr[g*24+15+:9]);
  end
  assign write_addr[14:0]=0;
  assign bounds_fault=|bad_address;
  request_t accepted_input;
  wire [31:0] serial=native_ordinal;
  // Native normalization, expressed with vector temporaries because the
  // small Icarus gate does not support struct-member part-select assignments.
  // Packed member order is the unchanged native request_t declaration.
  reg [29:0] clean_ra;
  reg [74:0] clean_wa;
  reg [79:0] clean_wm;
  reg [2559:0] clean_wd;
  always @*begin
   clean_ra=0;clean_wa=0;clean_wm=0;clean_wd=0;
   for(integer r=0;r<2;r=r+1)if(read_enable[r])clean_ra[r*15+:15]=read_addr[r*15+:15];
   for(integer w=0;w<5;w=w+1)if(write_enable[w])begin
    clean_wa[w*15+:15]=write_addr[w*15+:15];clean_wm[w*16+:16]=write_mask[w*16+:16];
    for(integer l=0;l<16;l=l+1)if(write_mask[w*16+l])clean_wd[w*512+l*32+:32]=write_data[w*512+l*32+:32];
   end
   accepted_input={serial,request_owner,read_enable,clean_ra,write_enable,clean_wa,clean_wd,clean_wm};
  end
  (* keep=1,dont_touch=1 *) request_t source_packet,source_check;
  (* keep=1,dont_touch=1 *) reply_t held_reply,held_check;
  reg warm,warm_check,ack_sent,ack_sent_check,poison,poison_check;
  reg [7:0] head_id,head_id_check;
  wire matching_reply=source_packet.owner==held_reply.owner&&source_packet.ordinal==held_reply.ordinal&&
      source_packet.we==held_reply.visible&&source_packet.wa==held_reply.wa&&source_packet.wm==held_reply.wm;
  wire bad=source_packet!=~source_check||held_reply!=~held_check||warm!=~warm_check||
      ack_sent!=~ack_sent_check||poison!=~poison_check||head_id!=~head_id_check;
  assign endpoint_fault=poison||bad||bounds_fault;
  always @(posedge fast_clk) begin
   if(!cold_n) begin
    source_packet<=0;source_check<={REQ_BITS{1'b1}};
    held_reply<=0;held_check<={REP_BITS{1'b1}};
    head_id<=0;head_id_check<=8'hff;
    warm<=0;warm_check<=1;ack_sent<=0;ack_sent_check<=1;poison<=0;poison_check<=1;
   end else begin
    if(request_accept&&!endpoint_fault) begin
     source_packet<=accepted_input;source_check<=~accepted_input;
     head_id<=request_id;head_id_check<=~request_id;
     warm<=request_warm;warm_check<=~request_warm;ack_sent<=0;ack_sent_check<=1;
    end
    if(head_ack_v)begin ack_sent<=1;ack_sent_check<=0;end
    if(bad||bounds_fault||(published_reply_v&&!matching_reply))begin poison<=1;poison_check<=0;end
    // This enable is the native matching protected-reply capture, not C8.
    if(checked_reply_capture) begin held_reply<=checked_reply;held_check<=~checked_reply;end
   end
  end
  assign captured_request=source_packet;assign captured_request_check=source_check;
  assign captured_reply=held_reply;assign captured_reply_check=held_check;
  // Native publication has already checked full owner+ordinal/enable/address/
  // mask and protected readback. The head debt owner independently matches
  // these ID/word/mask fields against its retained warm transaction.
  assign head_ack_v=published_reply_v&&held_reply.visible[1]&&warm&&!ack_sent&&matching_reply&&!endpoint_fault;
  assign head_ack_id=head_id;
  assign head_ack_word={9'b0,held_reply.wa[15+:15]};
  assign head_ack_mask=held_reply.wm[16+:16];
 end else begin : g_off
  assign request_checked_v=0;assign reply_checked_v=0;assign guard_busy=0;
  assign bounds_fault=0;assign endpoint_fault=0;assign captured_request=0;assign captured_request_check=0;
  assign captured_reply=0;assign captured_reply_check=0;assign head_ack_v=0;
  assign head_ack_id=0;assign head_ack_word=0;assign head_ack_mask=0;
 end endgenerate
endmodule

out/head_q_safe__wok_mask/ot_hdc_v41_fh_.text:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------------------------------------------
// ot_hdc_v41_fh_quad: one hardened QUADRANT of the margin-first fused head (redesign pass 2026-10-06). Four identical
// instances (gid strap 0..3) plus ot_hdc_v41_fh_head_top form ot_hdc_v41_fh_head_q, which is cycle-identical to
// ot_hdc_v41_fh_macro_ctx MARGIN=1 HARD_LANE=1 (CAPTURE, ALAT 7, RETURN_EXTRA 5, PROTECT_SPLIT 1). Nothing is added:
// the group's registers of fh_ctx / fh_add / sram_return_hardened are only regrouped into the quadrant:
//   in : the write mask / data ADDR_PIPE stage-1 registers (s_wmask, s_wdata), res_u, mask_q, o_mask1, o_addr1, the leaf-row / argmax-index / index-address group replicas, the group
//        copies of the return valid (u_rvg), fused select (u_selg) and index-write go (u_iwgg), the per-lane
//        request registers (ADDR_PIPE stage 2) - every input pin lands on one of these flops;
//   core: 16 hardened SRAM lane leaves (bank_id = {gid, lane}), the res_h delay line, 16 capture + FP32 add LAT 7
//        lanes, the fused/plain result select, the o_*1 / index-write port, the argmax leaves;
//   out: leaf, o_data, o_mask, o_addr, poison, group_fault - all flops.
// Index writes belong to group 0 (gid strap); o_addr takes the index address from its group replica iw_e_x, equal
// to the top's iaddr_r whenever an index write is selected (iaddr_r is held from go_fus acceptance to the write).
// ---------------------------------------------------------------------------------------------------------------
module ot_hdc_v41_fh_quad #(
    parameter integer W = 16, AW = 24, NW = 16, ALAT = 7, RETURN_EXTRA = 5,
    // QPIN (redesign r2): the request inputs (rok/rrow/wok/wrow) and the write mask/data land on a group input-pin
    // register before the per-lane request registers (ADDR_PIPE 3, +1 request cycle, RETURN_EXTRA = 6): no input pin
    // fans out across the quadrant.
    parameter integer QPIN = 0
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire [1:0]        gid,
    input  wire              rok,
    input  wire [8:0]        rrow,
    input  wire              wok,
    input  wire [8:0]        wrow,
    input  wire [W-1:0]      wr_mask_in,
    input  wire [W*32-1:0]   wr_data_in,
    input  wire [W*32-1:0]   res_in,
    input  wire [W-1:0]      o_mask1_in,
    input  wire [AW-1:0]     o_addr1_in,
    input  wire [W-1:0]      leaf_mask_in,
    input  wire [NW-1:0]     leaf_row_in,
    input  wire [NW-1:0]     am_idx_in,
    input  wire              rv_mid,
    input  wire              fsel_m,
    input  wire              iwg_m,
    input  wire [AW-1:0]     iw_e,
    output wire [(1+32+NW)*W-1:0] leaf,
    output reg  [W*32-1:0]   o_data,
    output reg  [W-1:0]      o_mask,
    output reg  [AW-1:0]     o_addr,
    output wire [W-1:0]      poison,
    output reg               group_fault
);
    localparam integer LW = $clog2(W);
    localparam integer CW = 1 + 32 + NW;
    // ---- input flops ---------------------------------------------------------------------------------------
    reg [W*32-1:0] res_u;
    reg [W-1:0] mask_q, o_mask1;
    reg [AW-1:0] o_addr1;
    always @(posedge clk) begin res_u <= res_in; mask_q <= leaf_mask_in; o_mask1 <= o_mask1_in; o_addr1 <= o_addr1_in; end
    wire [NW-1:0] row_qg, am_idx_x;
    wire [AW-1:0] iw_e_x;
    ot_hdc_v41_fh_kvec #(.N(NW)) u_rowq (.clk(clk), .d(leaf_row_in), .q(row_qg));
    ot_hdc_v41_fh_kvec #(.N(NW)) u_amg (.clk(clk), .d(am_idx_in), .q(am_idx_x));
    ot_hdc_v41_fh_kvec #(.N(AW)) u_iag (.clk(clk), .d(iw_e), .q(iw_e_x));
    wire protected_vg, fsel_g, iwg_g;
    ot_hdc_v41_fh_kreg u_rvg (.clk(clk), .rst_n(rst_n), .d(rv_mid), .q(protected_vg));
    ot_hdc_v41_fh_kreg u_selg (.clk(clk), .rst_n(rst_n), .d(fsel_m), .q(fsel_g));
    ot_hdc_v41_fh_kreg u_iwgg (.clk(clk), .rst_n(rst_n), .d(iwg_m), .q(iwg_g));
    // ---- SRAM lanes: ADDR_PIPE stage 2 (kept per-lane request register) + hardened lane leaf -----------------
    wire [W*32-1:0] ra_q;
    reg [W-1:0] s_wmask;
    reg [W*32-1:0] s_wdata;
    wire rok_q, wok_q;
    wire [8:0] rrow_q, wrow_q;
    generate if (QPIN) begin : g_pin
        reg [W-1:0] s_wmask0;
        reg [W*32-1:0] s_wdata0;
        reg rok_p, wok_p;
        reg [8:0] rrow_p, wrow_p;
        always @(posedge clk or negedge rst_n)
            if (!rst_n) begin rok_p <= 1'b0; wok_p <= 1'b0; end
            else begin rok_p <= rok; wok_p <= wok; end
        always @(posedge clk) begin rrow_p <= rrow; wrow_p <= wrow; s_wmask0 <= wr_mask_in; s_wdata0 <= wr_data_in;
                                    s_wmask <= s_wmask0; s_wdata <= s_wdata0; end
        assign rok_q = rok_p; assign wok_q = wok_p; assign rrow_q = rrow_p; assign wrow_q = wrow_p;
    end else begin : g_nopin
        always @(posedge clk) begin s_wmask <= wr_mask_in; s_wdata <= wr_data_in; end
        assign rok_q = rok; assign wok_q = wok; assign rrow_q = rrow; assign wrow_q = wrow;
    end endgenerate
    genvar l;
    generate for (l = 0; l < W; l = l + 1) begin : g_bank
        wire r_ok, w_ok;
        wire [8:0] r_row, w_row;
        wire [31:0] w_d;
        ot_hdc_v41_fh_quad_lane_req u_req (.clk(clk), .rst_n(rst_n),
            .read_ok_d(rok_q), .read_row_d(rrow_q), .write_ok_d(wok_q), .write_row_d(wrow_q), .wr_data_d(s_wdata[32*l+:32]),
            .read_ok(r_ok), .read_row(r_row), .write_ok(w_ok), .write_row(w_row), .wr_data(w_d));
        ot_hdc_v41_fh_sram_lane_hardened u_lane (
            .bank_id({gid, 4'(l)}),
            .clk(clk), .rst_n(rst_n), .read_ok(r_ok), .read_row(r_row),
            .write_ok(w_ok), .write_row(w_row), .wr_data(w_d),
            .rd_data(ra_q[32*l+:32]), .rd_valid(), .corrected(),
            .poisoned(poison[l]), .wr_committed());
    end endgenerate
    // ---- fused add lanes (ot_hdc_v41_fh_add CAPTURE + TREE, one group) --------------------------------------
    wire [W*32-1:0] res_h;
    ot_hdc_delay #(.W(W*32), .D(2 + RETURN_EXTRA)) u_rh (.clk(clk), .rst_n(rst_n), .d(res_u), .q(res_h));
    wire [W*32-1:0] fsum;
    wire [W-1:0] ffault, fused_lane_v, iwg;
    generate for (l = 0; l < W; l = l + 1) begin : g_fadd
        reg [31:0] addend_r, result_r;
        wire valid_in;
        always @(posedge clk) begin addend_r <= ra_q[32*l+:32]; result_r <= res_h[32*l+:32]; end
        ot_hdc_v41_fh_kreg u_v (.clk(clk), .rst_n(rst_n), .d(protected_vg), .q(valid_in));
        wire [1:0] err;
        wire vo;
        ot_hdc_fp32_add_lat #(.LAT(ALAT)) u_add (.clk(clk), .rst_n(rst_n), .valid_in(valid_in), .a(addend_r),
                                                 .b(result_r), .y(fsum[32*l +: 32]), .err(err), .valid_out(vo));
        assign ffault[l] = vo && (err != 2'd0);
        ot_hdc_v41_fh_kreg u_sel (.clk(clk), .rst_n(rst_n), .d(fsel_g), .q(fused_lane_v[l]));
        ot_hdc_v41_fh_kreg u_iwg (.clk(clk), .rst_n(rst_n), .d(iwg_g), .q(iwg[l]));
    end endgenerate
    always @(posedge clk or negedge rst_n)
        if (!rst_n) group_fault <= 1'b0; else group_fault <= |ffault;
    wire [W*32-1:0] res;
    generate for (l = 0; l < W; l = l + 1) begin : g_res
        assign res[32*l+:32] = fused_lane_v[l] ? fsum[32*l+:32] : res_u[32*l+:32];
    end endgenerate
    // ---- result port: o_*1 stage, the argmax-index write (group 0) ------------------------------------------
    reg [W*32-1:0] o_data1;
    always @(posedge clk) o_data1 <= res;
    wire idx_group = gid == 2'd0;
    wire [NW-1:0] index_local [0:W-1];
    wire [W-1:0] index_mask_local;
    generate for (l = 0; l < W; l = l + 1) begin : g_index_prepare
        ot_hdc_v41_fh_indexreg #(.NW(NW), .LW(LW), .LANE(l)) u_index (
            .clk(clk), .index_in(am_idx_x), .lane_in(iw_e_x[LW-1:0]),
            .index_q(index_local[l]), .mask_q(index_mask_local[l]));
    end endgenerate
    integer il;
    always @(posedge clk) begin
        for (il = 0; il < W; il = il + 1) begin
            o_data[32*il +: 32] <= iwg[il] ? ((idx_group && index_mask_local[il]) ? {{(32-NW){1'b0}}, index_local[il]} : 32'b0)
                                           : o_data1[32*il +: 32];
            o_mask[il] <= iwg[il] ? (idx_group && index_mask_local[il]) : o_mask1[il];
        end
        o_addr <= iwg[0] ? (idx_group ? (iw_e_x >> LW) : {AW{1'b0}}) : o_addr1;
    end
    // ---- argmax leaves ----------------------------------------------------------------------------------------
    function automatic [31:0] okey(input [31:0] v);
        okey = v[31] ? ~v : {1'b1, v[30:0]};
    endfunction
    generate for (l = 0; l < W; l = l + 1) begin : g_leaf
        reg [CW-1:0] c;
        always @(posedge clk) c <= {mask_q[l], okey(res[32*l +: 32]), row_qg};
        assign leaf[CW*l +: CW] = c;
    end endgenerate
endmodule

// Kept per-lane request register (ADDR_PIPE stage 2), the quadrant's own copy of ot_hdc_v41_fh_lane_req (same logic): the
// quadrant view is synthesised against the hardened lane LEAF (liberty), so it cannot read the lane RTL file.
(* keep_hierarchy *)
module ot_hdc_v41_fh_quad_lane_req(
    input wire clk,rst_n,read_ok_d,write_ok_d,
    input wire [8:0] read_row_d,write_row_d,
    input wire [31:0] wr_data_d,
    output reg read_ok,write_ok,
    output reg [8:0] read_row,write_row,
    output reg [31:0] wr_data
);
    always @(posedge clk or negedge rst_n)
        if(!rst_n) begin read_ok<=0; write_ok<=0; end
        else begin read_ok<=read_ok_d; write_ok<=write_ok_d; end
    always @(posedge clk) begin read_row<=read_row_d; write_row<=write_row_d; wr_data<=wr_data_d; end
endmodule

out/head_q_safe__fold_skip/ot_hdc_v41_fh.text:
`timescale 1ns/1ps
// ---------------------------------------------------------------------------------------------------------------
// ot_hdc_v41_fh_head_top: the registered TOP of the quadrant-structured fused head (redesign pass 2026-10-06), i.e.
// ot_hdc_v41_fh_macro_ctx MARGIN=1 HARD_LANE=1 (CAPTURE, ALAT 7, RETURN_EXTRA 5, PROTECT_SPLIT 1, RETIRE, VM_ENDPOINT,
// VM_GUARD) minus the four group datapaths that live in ot_hdc_v41_fh_quad. It keeps the tag / valid lines, the
// fused-add address generation and return-valid line, the centre copies of the group broadcast trees (u_rvm, u_selm,
// u_iwgm), the index-write state machine, the SRAM request decode with its ADDR_PIPE stage-1 registers (the per-lane
// group write_ok; mask/data stage-1 registers in the quadrants), the five-deep fault retirement, the checked endpoint
// (FPIPE: registered fault aggregation) and the argmax level-1 consumers. Every quadrant-facing output is a flop;
// every quadrant output arrives from a flop. Cycle-identical composition: ot_hdc_v41_fh_head_q.
// ---------------------------------------------------------------------------------------------------------------
module ot_hdc_v41_fh_head_top #(
    parameter integer W = 16, G = 4, IL = 8, AW = 24, NW = 16, ALAT = 7, RETURN_EXTRA = 5,
    parameter integer FPIPE = 1,
    parameter integer SAFE = 0,          // retirement SAFE + registered stand-in fold (with FPIPE=2)
    parameter integer ROWS = 505,
    parameter [AW-1:0] LG_BASE_WORD = 0
) (
    input  wire              clk,
    input  wire              rst_n,
    input wire commit_busy,commit_ack_v,
    input wire native_cold_n,native_request_ready,native_reply_capture,native_reply_v,
    input wire [31:0] native_ordinal,
    input wire [46:0] native_request_owner,
    input wire [1266:0] native_checked_reply,
    output wire native_request_checked_v,native_reply_checked_v,
    output wire [3:0] native_permission_capture,
    output wire [2830:0] native_captured_request,
    output wire [1266:0] native_captured_reply,
    input wire [7:0] commit_ack_id,
    input wire [23:0] commit_ack_word,
    input wire [15:0] commit_ack_mask,
    output wire commit_warm,commit_debt,
    output wire [7:0] commit_id,
    input  wire              s3_v_in,
    input  wire [1+1+1+1+1+2+AW+AW+3*(NW+1)+2+AW+3+AW+1-1:0] a_tag_p_in,
    input wire [G-1:0] wr_en,
    input wire [G*AW-1:0] wr_addr,
    output wire [G-1:0]      ra_re,
    output wire [G*AW-1:0]   ra_addr,
    input  wire              go_fus,
    input  wire [AW-1:0]     i_iaddr,
    input  wire [4:0]        busy_in,
    input  wire [G-1:0]      o_we1_in,
    input  wire              tv_in,
    input  wire              ov1_in,
    output wire [1+1+1+1+1+2+AW+AW+3*(NW+1)+2+AW+3+AW+1-1:0] r_tag,
    output wire               r_v,
    output wire [(1+32+NW)*G*W-1:0] leaf,
    output wire  [G-1:0]      o_we,
    output wire  [G*AW-1:0]   o_addr,
    output wire  [G*W-1:0]    o_mask,
    output wire  [G*W*32-1:0] o_data,
    output wire              fault,
    output wire [0:0] argmax_level1,
    // quadrant interface (to: flops here; from: flops in the quadrants)
    output reg  [G-1:0]      q_rok,
    output reg  [G*9-1:0]    q_rrow,
    output reg  [G-1:0]      q_wok,
    output reg  [G*9-1:0]    q_wrow,
    output wire [G-1:0]      q_rv_mid,
    output wire [G-1:0]      q_fsel_m,
    output wire [G-1:0]      q_iwg_m,
    output wire [AW-1:0]     q_iw_e,
    input  wire [(1+32+NW)*G*W-1:0] q_leaf,
    input  wire [G*W*32-1:0] q_o_data,
    input  wire [G*W-1:0]    q_o_mask,
    input  wire [G*AW-1:0]   q_o_addr,
    input  wire [G*W-1:0]    q_poison,
    input  wire [G-1:0]      q_group_fault
);
    localparam integer LW = $clog2(W);
    localparam integer LG = $clog2(G);
    localparam integer OD = 6 * LG;
    localparam integer LV = $clog2(G * W);
    localparam integer TW = 1 + 1 + 1 + 1 + 1 + 2 + AW + AW + 3 * (NW + 1) + 2 + AW + 3 + AW + 1;
    localparam integer CAPTURE = 1;
    localparam integer DF = 2 + RETURN_EXTRA + CAPTURE + ALAT;
    // ======================= ot_hdc_v41_fh_ctx (MARGIN=1, CAPTURE=1, RETIRE=1) control ===========================
    reg [TW-1:0]     a_tag_p;
    reg [4:0]        busy_q;
    reg              s3_v;
    reg [G-1:0]      o_we1;
    reg [LV:0]       tv;
    reg              ov1, ov;
    reg [TW-1:0]     r_tag_q;
    reg              r_v_q;
    reg [G-1:0]      o_we_q;
    reg              warm_emit;
    always @(posedge clk) a_tag_p <= a_tag_p_in;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin busy_q <= 0; s3_v <= 0; o_we1 <= 0; tv <= 0; ov1 <= 0; ov <= 0; end
        else begin
            busy_q <= busy_in; s3_v <= s3_v_in; o_we1 <= o_we1_in; tv <= {tv[LV-1:0], tv_in}; ov1 <= ov1_in;
            ov <= ov1;
        end
    end
    wire [10+OD:0] vline;
    ot_hdc_vline #(.D(10 + OD)) u_v (.clk(clk), .rst_n(rst_n), .v(s3_v), .vd(vline));
    reg  [TW-1:0] a_tag;
    always @(posedge clk) a_tag <= a_tag_p;
    wire          t_v = vline[10 + OD];
    wire          u_fus = a_tag[0];
    wire          t_v_p = vline[10 + OD - 1];
    wire          p_last, p_oen, p_amax, p_wsrc, p_mmode, p_fus;
    wire [1:0]    p_split, p_hg;
    wire [AW-1:0] p_ogs, p_oa, p_ots, p_ops;
    wire [2:0]    p_m;
    wire [NW:0]   p_nb, p_lb, p_nout;
    assign {p_last, p_oen, p_amax, p_wsrc, p_mmode, p_split, p_oa, p_ots, p_nb, p_lb, p_nout, p_hg, p_ogs, p_m,
            p_ops, p_fus} = a_tag_p;
    wire [LG:0]   p_tq = (G >> p_hg) - 1;
    wire [LG:0]   p_ports = G >> p_split;
    wire [TW-1:0] f_tag_p;
    ot_hdc_delay #(.W(TW), .D(DF - 1)) u_ftag (.clk(clk), .rst_n(rst_n), .d(a_tag), .q(f_tag_p));
    wire [DF:0] fline;
    ot_hdc_vline #(.D(DF)) u_fv (.clk(clk), .rst_n(rst_n), .v(t_v && u_fus), .vd(fline));
    always @(posedge clk) r_tag_q <= fline[DF - 1] ? f_tag_p : a_tag_p;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) r_v_q <= 1'b0;
        else r_v_q <= fline[DF - 1] || (t_v_p && !p_fus);
    end
    // ---- ot_hdc_v41_fh_add: address generation, return valid (TREE centre copies) ----------------------------
    localparam integer MPI = 0;
    integer rq;
    reg [G-1:0]    re0, ra_re_q;
    reg [G*AW-1:0] ta, tb, tc, ra_addr_q;
    assign ra_re = ra_re_q; assign ra_addr = ra_addr_q;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin re0 <= 0; ra_re_q <= 0; end
        else begin
            for (rq = 0; rq < G; rq = rq + 1)
                re0[rq] <= t_v_p && p_fus && p_last && (rq < p_ports) && (MPI < p_m);
            ra_re_q <= re0;
        end
    end
    localparam [AW-1:0] MPI_W = MPI;
    wire [AW-1:0] ots3, ogs3, mops, ta_n;
    ot_hdc_ksadd_k #(.W(AW)) u_o3 (.a(p_ots), .b(p_ots << 1), .cin(1'b0), .s(ots3), .cout());
    ot_hdc_ksadd_k #(.W(AW)) u_g3 (.a(p_ogs), .b(p_ogs << 1), .cin(1'b0), .s(ogs3), .cout());
    assign mops = MPI_W * p_ops;
    ot_hdc_ksadd_k #(.W(AW)) u_ta (.a(p_oa), .b(mops), .cin(1'b0), .s(ta_n), .cout());
    function automatic [AW-1:0] kx(input [1:0] k, input [AW-1:0] x, input [AW-1:0] x3);
        kx = (k == 2'd0) ? {AW{1'b0}} : (k == 2'd1) ? x : (k == 2'd2) ? (x << 1) : x3;
    endfunction
    genvar ga;
    generate for (ga = 0; ga < G; ga = ga + 1) begin : g_ra
        wire [AW-1:0] sa = ta[ga*AW +: AW], sb = tb[ga*AW +: AW], sc = tc[ga*AW +: AW];
        wire [AW-1:0] cs_s = sa ^ sb ^ sc;
        wire [AW-1:0] cs_c = ((sa & sb) | (sa & sc) | (sb & sc)) << 1;
        wire [AW-1:0] sum;
        ot_hdc_ksadd_k #(.W(AW)) u_sum (.a(cs_s), .b(cs_c), .cin(1'b0), .s(sum), .cout());
        always @(posedge clk) begin
            ta[ga*AW +: AW] <= ta_n;
            tb[ga*AW +: AW] <= kx(2'(ga & p_tq), p_ots, ots3);
            tc[ga*AW +: AW] <= kx(2'(ga >> (LG - p_hg)), p_ogs, ogs3);
            ra_addr_q[ga*AW +: AW] <= sum;
        end
    end endgenerate
    reg hv0, hv1, ah_v;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin hv0 <= 1'b0; hv1 <= 1'b0; ah_v <= 1'b0; end
        else begin hv0 <= t_v_p && p_fus && p_last; hv1 <= hv0; ah_v <= hv1; end
    end
    wire rv_pre;
    ot_hdc_delay #(.W(1), .D(RETURN_EXTRA - 2)) u_return_valid (.clk(clk), .rst_n(rst_n), .d(ah_v), .q(rv_pre));
    // ---- index-write state (ctx, RETIRE, IW_EXTRA = 1) ---------------------------------------------------------
    wire retire_busy, retire_warm_ack;
    reg iw_pend, iw_issued, iw_go, iw_go2, iw_go3;
    reg [AW-1:0] iaddr_r;
    wire iw_write_go = iw_go3;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin iw_go2 <= 0; iw_go3 <= 0; end else begin iw_go2 <= iw_go; iw_go3 <= iw_go2; end
    wire drained_nx = !retire_busy && !(|busy_q) && !s3_v && !(|vline) && !(|tv[LV-1:0]) && !ov1 && !ov && !(|fline);
    wire iw_go_n = iw_pend && !iw_go && !iw_go2 && !iw_go3 && drained_nx && !iw_issued;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin iw_pend <= 1'b0; iw_issued <= 0; warm_emit <= 0; iaddr_r <= 0; iw_go <= 1'b0; end
        else begin
            iw_go <= iw_go_n; warm_emit <= iw_write_go;
            if (go_fus && !iw_pend && !retire_busy) begin
                iw_pend <= 1'b1; iw_issued <= 0; iaddr_r <= i_iaddr;
            end else if (iw_write_go) iw_issued <= 1;
            else if (retire_warm_ack) begin iw_pend <= 0; iw_issued <= 0; end
        end
    end
    assign q_iw_e = iaddr_r + MPI;
    genvar gq;
    generate for (gq = 0; gq < G; gq = gq + 1) begin : g_centre
        ot_hdc_v41_fh_kreg u_rvm (.clk(clk), .rst_n(rst_n), .d(rv_pre), .q(q_rv_mid[gq]));
        ot_hdc_v41_fh_kreg u_selm (.clk(clk), .rst_n(rst_n), .d(fline[DF-3]), .q(q_fsel_m[gq]));
        ot_hdc_v41_fh_kreg u_iwgm (.clk(clk), .rst_n(rst_n), .d(iw_go_n), .q(q_iwg_m[gq]));
    end endgenerate
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) o_we_q <= 0;
        else if (iw_write_go) o_we_q <= {{(G-1){1'b0}}, 1'b1};
        else o_we_q <= o_we1;
    end
    // ======================= ot_hdc_v41_fh_sram_return_hardened request decode + ADDR_PIPE stage 1 ==============
    wire [G-1:0] read_ok, write_ok;
    wire [G*9-1:0] read_row, write_row;
    reg [G-1:0] address_fault;
    generate for (ga = 0; ga < G; ga = ga + 1) begin : g_address
        wire [AW-1:0] ra = ra_addr[ga*AW+:AW] - LG_BASE_WORD;
        wire [AW-1:0] wa = wr_addr[ga*AW+:AW] - LG_BASE_WORD;
        assign read_ok[ga] = ra_re[ga] && ra_addr[ga*AW+:AW] >= LG_BASE_WORD && ra[LG-1:0] == ga && (ra >> LG) < ROWS;
        assign write_ok[ga] = wr_en[ga] && wr_addr[ga*AW+:AW] >= LG_BASE_WORD && wa[LG-1:0] == ga && (wa >> LG) < ROWS;
        assign read_row[ga*9+:9] = 9'(ra >> LG);
        assign write_row[ga*9+:9] = 9'(wa >> LG);
        always @(posedge clk or negedge rst_n)
            if (!rst_n) address_fault[ga] <= 0;
            else if ((ra_re[ga] && !read_ok[ga]) || (wr_en[ga] && !write_ok[ga])) address_fault[ga] <= 1;
    end endgenerate
    // (the write mask / data stage-1 registers sit at the quadrant pins: wr_mask / wr_data feed through)
    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin q_rok <= 0; q_wok <= 0; end
        else begin q_rok <= read_ok; q_wok <= write_ok; end
    always @(posedge clk) begin q_rrow <= read_row; q_wrow <= write_row; end
    // ======================= ot_hdc_v41_fh_macro_ctx: endpoint, retirement, consumers ============================
    wire native_ack_v, native_fault, native_bounds_fault, native_guard_busy;
    wire [7:0] native_ack_id;
    wire [23:0] native_ack_word;
    wire [15:0] native_ack_mask;
    wire [2830:0] native_request_check_full;
    wire [1266:0] native_reply_check_full;
    ot_hdc_v41_fh_vm_endpoint_ctx #(.ENABLE(1),.CHECK_PIPE(1),.MARGIN(1),.FPIPE(FPIPE)) u_native (
        .fast_clk(clk),.cold_n(native_cold_n),
        .request_accept((|o_we)&&native_request_ready),.request_warm(commit_warm),
        .checked_reply_capture(native_reply_capture),.published_reply_v(native_reply_v),
        .native_ordinal(native_ordinal),.request_owner(native_request_owner),.request_id(commit_id),
        .head_we(o_we),.head_addr(o_addr),.head_mask(o_mask),.head_data(o_data),
        .checked_reply(native_checked_reply),.bounds_fault(native_bounds_fault),.endpoint_fault(native_fault),
        .captured_request(native_captured_request),.captured_request_check(native_request_check_full),
        .captured_reply(native_captured_reply),.captured_reply_check(native_reply_check_full),
        .request_checked_v(native_request_checked_v),.reply_checked_v(native_reply_checked_v),.guard_busy(native_guard_busy),
        .head_ack_v(native_ack_v),.head_ack_id(native_ack_id),.head_ack_word(native_ack_word),.head_ack_mask(native_ack_mask));
    (* keep=1,dont_touch=1 *) reg request_v,request_check,reply_v,reply_check;
    assign native_permission_capture={reply_check,reply_v,request_check,request_v};
    always @(posedge clk) begin
        if(!native_cold_n) begin
            request_v<=0;request_check<=1;reply_v<=0;reply_check<=1;
        end else begin
            request_v<=native_request_checked_v;request_check<=~native_request_checked_v;
            reply_v<=native_reply_checked_v;reply_check<=~native_reply_checked_v;
        end
    end
    localparam integer PW=5512;
    wire parent_fault, rv, rw, retired_warm_payload, retired_ov, retired_leaf_v;
    wire child_leaf_v = tv[0], child_ov = ov;
    wire [PW-1:0] packet={q_leaf,o_we_q,q_o_addr,q_o_mask,q_o_data,r_tag_q,r_v_q,child_ov,child_leaf_v,warm_emit};
    wire [PW-1:0] retired;
    wire [63:0] veto;
    wire [3:0] write_veto,retired_we;
    wire [3135:0] retired_leaf;
    wire [TW-1:0] raw_tag_out;
    wire raw_v_out;
    ot_hdc_v41_fh_retire_parent #(.ENABLE(1),.PAYLOAD_BITS(PW),.MARGIN(1),.SAFE(SAFE)) u_parent (
        .clk(clk),.rst_n(rst_n),.packet_v(r_v_q||child_ov||(|o_we_q)||warm_emit||child_leaf_v),
        .warm(warm_emit),.packet(packet),.warm_word(q_o_addr[23:0]),.warm_mask(q_o_mask[15:0]),
        .poison(q_poison),.address_fault(address_fault),.arithmetic_fault(native_fault),.group_fault(q_group_fault),
        .sink_busy(commit_busy||native_guard_busy),.ack_v(native_ack_v),.ack_id(native_ack_id),
        .ack_word(native_ack_word),.ack_mask(native_ack_mask),
        .retired_v(rv),.retired_warm(rw),.retired_packet(retired),.retired_id(commit_id),
        .lane_veto(veto),.write_veto(write_veto),.busy(retire_busy),.warm_ack(retire_warm_ack),
        .fault(parent_fault),.warm_debt(commit_debt));
    assign {retired_leaf,retired_we,o_addr,o_mask,o_data,raw_tag_out,raw_v_out,
        retired_ov,retired_leaf_v,retired_warm_payload}=retired;
    assign o_we=rv?(retired_we&~write_veto):4'b0;
    assign commit_warm=rw&&(|o_we);
    genvar l;
    for(l=0;l<64;l=l+1) begin : g_local_veto
        assign leaf[l*49+:49]={retired_leaf[l*49+48]&&!veto[l],retired_leaf[l*49+:48]};
    end
    assign fault=parent_fault;
    assign r_tag = raw_tag_out; assign r_v = raw_v_out;
    wire [(1+32+NW)*(G*W/2)-1:0] argmax_level1_full;
    for(genvar p=0;p<G*W/2;p=p+1) begin : g_argmax_consumer
        localparam integer CW=1+32+NW;
        wire [CW-1:0] x0=leaf[CW*(2*p)+:CW];
        wire [CW-1:0] x1=leaf[CW*(2*p+1)+:CW];
        wire x0_wins=x0[CW-1]&&(!x1[CW-1]||x0[CW-2-:32]>x1[CW-2-:32]||
            (x0[CW-2-:32]==x1[CW-2-:32]&&x0[NW-1:0]<x1[NW-1:0]));
        reg [CW-1:0] c;
        always @(posedge clk) c<=x0_wins?x0:x1;
        assign argmax_level1_full[CW*p+:CW]=c;
    end
    if(SAFE) begin : g_fold_reg   // stand-in observation fold, registered (SAFE)
            localparam integer NF=((1+32+NW)*(G*W/2)+63)/64;
            wire [NF*64-1:0] ff={{(NF*64-(1+32+NW)*(G*W/2)){1'b0}},argmax_level1_full};
            reg [NF-1:0] f1; reg f2;
            integer fi;
            always @(posedge clk) begin for(fi=0;fi<NF;fi=fi+1) f1[fi]<=^ff[fi*64+:64]; f2<=^f1; end
            assign argmax_level1=^f1;
        end else begin : g_fold_direct
            assign argmax_level1=^argmax_level1_full;
        end
endmodule
